function validate(input) {
  const [{ Stadium = [] }] = input;
  const ids = new Set(), dates = new Set();
  for (const [id, date, people] of Stadium) {
    if (id === null || date === null || people === null) return 'id, visit_date and people cannot be null.';
    if (id < 1) return 'id must be positive.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `visit_date ${date} must look like 2017-01-31.`;
    if (ids.has(id)) return `id ${id} appears twice.`;
    if (dates.has(date)) return `visit_date ${date} appears twice.`;
    if (people < 0) return 'people cannot be negative.';
    ids.add(id);
    dates.add(date);
  }
  const sorted = [...Stadium].sort((a, b) => a[0] - b[0]);
  for (let i = 1; i < sorted.length; i++) if (sorted[i][1] <= sorted[i - 1][1]) return 'Dates must increase with id.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const crowds = [0, 10, 50, 99, 100, 101, 145, 150, 199, 1455];
  let day = Date.UTC(2017, 0, 1) + Math.floor(rand() * 30) * 86400000;
  let id = 1 + Math.floor(rand() * 3);
  const rows = [];
  for (let i = 0; i < count; i++) {
    // Mostly busy days so runs form; ids occasionally skip, which breaks a run even when dates do not.
    const people = rand() < 0.7 ? crowds[4 + Math.floor(rand() * 6)] : crowds[Math.floor(rand() * 4)];
    rows.push([id, new Date(day).toISOString().slice(0, 10), people]);
    id += rand() < 0.12 ? 2 : 1;
    day += (rand() < 0.2 ? 2 : 1) * 86400000;
  }
  // Stored row order does not follow id; the query must sort.
  for (let i = rows.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rows[i], rows[j]] = [rows[j], rows[i]];
  }
  return [{ Stadium: rows }];
}
